<?php $e = static fn (mixed $v): string => App\Core\View::e($v); ?><section class="page-stack"><div class="section-heading"><div><p class="eyebrow">Campeonato #<?= (int) $championshipId ?></p><h1>Prestação de contas</h1><p class="muted">Exports CSV abrem como planilhas em Excel e LibreOffice. Cada download é registrado em auditoria.</p></div><a class="button secondary" href="<?= $e(App\Core\Config::url('/prestacao')) ?>">Voltar</a></div><section class="metric-grid"><?php foreach ($summary as $label => $value): ?><article class="metric-card"><span><?= $e(str_replace('_', ' ', $label)) ?></span><strong><?= (int) $value ?></strong></article><?php endforeach; ?></section><article class="panel"><h2>Downloads</h2><div class="quick-actions"><?php foreach (['partidas' => 'Partidas', 'atletas' => 'Atletas e inscrições', 'sumulas' => 'Súmulas', 'evidencias' => 'Evidências fotográficas'] as $kind => $label): ?><a class="button secondary" href="<?= $e(App\Core\Config::url('/prestacao/campeonatos/' . $championshipId . '/exportar/' . $kind)) ?>"><?= $e($label) ?> CSV</a><?php endforeach; ?></div></article></section>
